/**
 * Router المركزي — React Router v7 (createBrowserRouter) + Lazy + Guards.
 * التسلسل: authGuard (جلسة) → portalGuard (بوابة) → صفحات البوابة.
 */
import { lazy } from '@lib/router/lazy'
import { RouteHydrateFallback } from './RouteHydrateFallback'
import { Suspense } from 'react'
import { createBrowserRouter, redirect } from 'react-router'
import { PUBLIC_ROUTES, PORTAL_ROUTES } from './routes.config'
import { authGuard } from './guards/auth.guard'
import { portalGuard } from './guards/portal.guard'
import { resolvePortal } from './portal.router'
import { LoadingSpinner } from '@components/feedback/LoadingSpinner'
import { ErrorBoundary } from '@components/feedback/ErrorBoundary'

const ForbiddenPage = lazy(() => import('@portals/public/pages/Forbidden/ForbiddenPage'))
const NotFoundPage = lazy(() => import('@portals/public/pages/NotFound/NotFoundPage'))

export const router = createBrowserRouter([
  // ── الجذر: موجّه ذكي حسب الجلسة ──
  {
    path: '/',
    // عنصر صريح: الـloader يعيد التوجيه دائماً، لكن React Router يحذّر (ويُرسم فارغاً) إن غاب العنصر
    element: <LoadingSpinner fullScreen />,
    HydrateFallback: RouteHydrateFallback,
    loader: async () => {
      const { authenticated, session } = await authGuard()
      if (!authenticated) return redirect('/login')
      const resolution = resolvePortal(session?.roles ?? [])
      if (resolution.type === 'single') return redirect(resolution.path)
      return redirect('/403')
    },
  },

  // ── المسارات العامة (تسجيل دخول/استعادة) ──
  ...PUBLIC_ROUTES.map((r) => ({
    path: r.path,
    element: (
      <ErrorBoundary>
        <Suspense fallback={<LoadingSpinner fullScreen />}>
          <r.component />
        </Suspense>
      </ErrorBoundary>
    ),
  })),

  // ── البوابات المحمية ──
  ...PORTAL_ROUTES.map((p) => ({
    path: p.path,
    element: (
      <ErrorBoundary>
        <Suspense fallback={<LoadingSpinner fullScreen />}>
          {/* القوقعة (AppShell) تحتوي Outlet الصفحات بنفسها — لا Outlet ثانٍ هنا وإلا تُرسم كل صفحة مرتين (نسخة خفية أسفل الشاشة) */}
          <p.shell />
        </Suspense>
      </ErrorBoundary>
    ),
    HydrateFallback: RouteHydrateFallback,
    loader: async () => {
      const { authenticated, session } = await authGuard()
      if (!authenticated) return redirect('/login')

      const decision = portalGuard(session, p.portal as Parameters<typeof portalGuard>[1])
      if (decision.decision === 'redirect' && decision.redirectTo) {
        return redirect(decision.redirectTo)
      }
      if (decision.decision === 'denied') return redirect('/403')
      return null
    },
    children: p.children ?? [],
  })),

  // رابط الإشعار العام للتبليغ → يعاد توجيهه إلى وارد بوابة المستخدم الأساسية
  {
    path: '/announcements/:announcementId?',
    HydrateFallback: RouteHydrateFallback,
    loader: async ({ params }) => {
      const { authenticated, session } = await authGuard()
      if (!authenticated) return redirect('/login')
      const resolution = resolvePortal(session?.roles ?? [])
      if (resolution.type !== 'single') return redirect('/403')
      return redirect(`${resolution.path}/announcements/inbox${params.announcementId ? '/' + params.announcementId : ''}`)
    },
  },

  // بوابة الكشوفات القديمة أُلغيت (00170) → وحدة الكشوفات داخل غرفة العمليات
  { path: '/disclosures/*', HydrateFallback: RouteHydrateFallback, loader: () => redirect('/ops-room/disclosures') },

  // 403 — دخول بوابة غير مصرح بها
  {
    path: '/403',
    element: (
      <ErrorBoundary>
        <Suspense fallback={<LoadingSpinner fullScreen />}>
          <ForbiddenPage />
        </Suspense>
      </ErrorBoundary>
    ),
  },

  // 00412: أي مسار غير معروف خارج البوابات — 404 حقيقية بدل إعادة توجيه صامتة إلى الجذر.
  // غير المسجّل يذهب إلى صفحة الدخول كما كان؛ المسجّل يرى 404 ويبقى مساره في شريط العنوان.
  {
    path: '*',
    element: (
      <ErrorBoundary>
        <Suspense fallback={<LoadingSpinner fullScreen />}>
          <NotFoundPage />
        </Suspense>
      </ErrorBoundary>
    ),
    HydrateFallback: RouteHydrateFallback,
    loader: async () => {
      const { authenticated } = await authGuard()
      if (!authenticated) return redirect('/login')
      return null
    },
  },
])

