/**
 * مولّد مسارات الوحدات — الإصلاح الجذري لثغرة إعادة التوجيه:
 * كل وحدة في الشريط الجانبي تحصل على Route فعلياً (صفحة حقيقية أو Placeholder)،
 * فلا يبقى أي رابط يسقط في wildcard {*} → لا عودة مفاجئة لصفحة الدخول.
 * البوابات ذات الصفحات الجاهزة تمرر customRoutes فتُستخدم بدل الـ Placeholder.
 */
import { lazy } from '@lib/router/lazy'
import { Suspense, type ReactNode } from 'react'
import { Navigate, matchPath, type RouteObject } from 'react-router'
import { MANUAL_ATTENDANCE_PORTALS, MANUAL_ATTENDANCE_SEGMENT, PORTAL_UNITS } from '@config/portals.config'
import type { PortalId } from '@lib/constants/portals.constants'
import { LoadingSpinner } from '@components/feedback/LoadingSpinner'

const ApprovalInbox = lazy(() => import('@portals/admin-ops/pages/Requests/TeamRequestsPage'))
const UnitPlaceholder = lazy(() => import('@components/layout/UnitPlaceholder'))
const ManualAttendancePage = lazy(() => import('@features/attendance-manual/pages/ManualAttendancePage'))   // الحضور اليدوي: صفحة واحدة عامة لكل البوابات
const NotFoundPage = lazy(() => import('@portals/public/pages/NotFound/NotFoundPage'))
const AnnouncementInbox = lazy(() => import('@components/executive/AnnouncementInbox'))
const AnnouncementDetail = lazy(() => import('@components/executive/AnnouncementInbox').then((m) => ({ default: m.AnnouncementDetail })))

/** وارد التبليغات متاح في كل بوابة على نفس المسار النسبي (يستهدفه إشعار التبليغ) */
export const ANNOUNCEMENT_INBOX_PATH = 'announcements/inbox'

function suspense(node: ReactNode): ReactNode {
  return <Suspense fallback={<LoadingSpinner fullScreen />}>{node}</Suspense>
}

export function buildPortalRoutes(
  portal: PortalId,
  customRoutes: RouteObject[] = [],
): RouteObject[] {
  const portalPath = '/' + portal
  const units = PORTAL_UNITS[portal] ?? []

  const byRel = new Map<string, RouteObject>()
  for (const route of customRoutes) {
    // الرئيسية تأتي بمسار '' (فارغ) — typeof يميّزها عن undefined، وإلا فلا تدخل الخريطة
    // وتستبدل صفحتها الحقيقية بـ UnitPlaceholder (ثغرة «قيد التطوير» على الرئيسية)
    if (typeof route.path === 'string') byRel.set(route.path, route)
  }

  // أي حساب مُعيّن في سلسلة يحتاج وارداً في بوابته، مع بقاء المسارات المخصصة كما هي.
  if (portal !== 'public' && !byRel.has('approvals')) {
    byRel.set('approvals', { path: 'approvals', element: suspense(<ApprovalInbox title="طلبات الموافقة" />) })
  }

  // الحضور اليدوي عند تعطل البصمة: صفحة عامة مبنية مرة واحدة تُسجَّل لكل بوابة تملك موظفين (ظهورها في الشريط مشروط بتفعيل ساريٍ)
  if ((MANUAL_ATTENDANCE_PORTALS as readonly PortalId[]).includes(portal) && !byRel.has(MANUAL_ATTENDANCE_SEGMENT)) {
    byRel.set(MANUAL_ATTENDANCE_SEGMENT, { path: MANUAL_ATTENDANCE_SEGMENT, element: suspense(<ManualAttendancePage portal={portal} />) })
  }

  const children: RouteObject[] = []
  const covered = new Set<string>()

  const servedByParamRoute = (rel: string): boolean =>
    customRoutes.some((r) => typeof r.path === 'string' && r.path.includes(':') && matchPath({ path: r.path, end: true }, '/' + rel) !== null)

  const resolve = (absPath: string): RouteObject => {
    const rel = absPath === portalPath ? '' : absPath.slice(portalPath.length + 1)
    const custom = byRel.get(rel)
    if (custom?.element) {
      return { path: rel || undefined, index: rel === '', element: custom.element }
    }
    return {
      path: rel || undefined,
      index: rel === '',
      element: suspense(<UnitPlaceholder portal={portal} unitPath={absPath} />),
    }
  }

  for (const unit of units) {
    children.push(resolve(unit.path))
    covered.add(unit.path === portalPath ? '' : unit.path.slice(portalPath.length + 1))
    for (const child of unit.children ?? []) {
      const rel = child.path.slice(portalPath.length + 1)
      // 00279/00280: طفل يخدمه مسار مخصص بمعامل (devops/git ← devops/:slug) لا يأخذ مساراً ثابتاً خاصاً
      // (كان يسقط في Placeholder «قيد التطوير»، وبمسار ثابت يفقد المعامل slug) — يُترك لمسار المعامل الذي يُضاف أدناه
      if (!byRel.has(rel) && servedByParamRoute(rel)) continue
      children.push(resolve(child.path))
      covered.add(rel)
    }
  }

  // مسارات مخصصة خارج الشريط (مثل صفحة التفاصيل :userId) — تُضاف كما هي
  for (const route of customRoutes) {
    if (route.path && !covered.has(route.path)) children.push(route)
  }

  // وارد التبليغات + تفصيل تبليغ — في كل بوابة بلا استثناء
  if (!covered.has(ANNOUNCEMENT_INBOX_PATH)) children.push({ path: ANNOUNCEMENT_INBOX_PATH, element: suspense(<AnnouncementInbox />) })
  children.push({ path: `${ANNOUNCEMENT_INBOX_PATH}/:announcementId`, element: suspense(<AnnouncementDetail />) })

  // 00412: أي رابط غير مسجّل **داخل البوابة** يعرض 404 داخل القوقعة (كان يسقط في wildcard العام
  // → إعادة توجيه صامتة إلى الرئيسية، فيضيع المسار ويظن المستخدم أن الصفحة موجودة)
  children.push({ path: '*', element: suspense(<NotFoundPage inPortal />) })

  // فهرس البوابة: أول وحدة (إلا إن كانت الوحدة الأولى هي الجذر — عندها صارت index أعلاه)
  const first = units[0]
  if (first && first.path !== portalPath && !children.some((c) => c.index)) {
    children.push({ index: true, element: <Navigate to={first.path} replace /> })
  }

  return children
}
