/**
 * مسارات بوابة المحطة التحويلية — النمط الموحد:
 *  · ''          → لوحة التقارير (الداشبورد)
 *  · weights     → صفحة الأوزان (النموذج + الدفتر + التصدير)
 *  · weights/log → نفس وحدة الأوزان (الإدخال)
 *  · saksat      → السكسات والنسافات الخارجة (القوائم فقط · الوصول آلي من GPS)
 *  · trips       → (00332) أُدمجت في وحدة السكسات والنسافات — تحويل تلقائي
 *  · fines       → الغرامات (قيد الإنشاء)
 *  · archive     → أرشيف المحطة (الحذف/الأرشفة نحو IT)
 *
 * ملاحظة: أُلغيت وحدة «الحضورية» من هذه البوابة — الحضور والانصراف من اختصاص
 * بوابة الموارد البشرية (HR) ولا يُدار هنا.
 */
import { lazy } from '@lib/router/lazy'
import { Suspense, type ReactNode } from 'react'
import { Navigate, type RouteObject } from 'react-router'
import { LoadingSpinner } from '@components/feedback/LoadingSpinner'

const StationDashboard = lazy(() => import('./pages/Dashboard/StationDashboard'))
const WeightsPage = lazy(() => import('./pages/Weights/WeightsPage'))
const SaksatPage = lazy(() => import('./pages/Saksat/SaksatPage'))
const CarrierPage = lazy(() => import('./pages/Carrier/CarrierPage'))
const FinesPage = lazy(() => import('./pages/Fines/FinesPage'))
const StationArchivePage = lazy(() => import('./pages/Archive/StationArchivePage'))
const StationEmployeesPage = lazy(() => import('./pages/Employees/StationEmployeesPage'))   // 00211: الموظفون (قسم المحطة فقط)
const StationRequestsPage = lazy(() => import('./pages/Requests/StationRequestsPage'))   // 00212: الطلبات (إجازات/زمنيات قسم المحطة)
const StationProceduresPage = lazy(() => import('./pages/Procedures/StationProceduresPage'))   // 00213: الإجراءات (تعيين/إنهاء خدمة قسم المحطة)
const StationDisclosuresPage = lazy(() => import('./pages/Disclosures/StationDisclosuresPage'))   // 00214: الكشوفات (موظفو قسم المحطة فقط)
const StationVehicleMovementsPage=lazy(()=>import('./pages/VehicleMovements/StationVehicleMovementsPage'))

const s = (node: ReactNode): ReactNode => (
  <Suspense fallback={<LoadingSpinner fullScreen />}>{node}</Suspense>
)

export const customRoutes: RouteObject[] = [
  { path: '', element: s(<StationDashboard />) },
  { path: 'weights', element: s(<WeightsPage />) },
  { path: 'weights/log', element: s(<WeightsPage />) },
  { path: 'saksat', element: s(<SaksatPage />) },
  { path: 'trips', element: <Navigate to="/transfer-station/saksat" replace /> },   // 00332: دمج
  { path: 'carrier', element: s(<CarrierPage />) },
  { path:'vehicle-movements',element:s(<StationVehicleMovementsPage/>) },
  { path: 'employees', element: s(<StationEmployeesPage />) },
  { path: 'requests', element: s(<StationRequestsPage />) },
  { path: 'procedures', element: s(<StationProceduresPage />) },
  { path: 'disclosures', element: s(<StationDisclosuresPage />) },
  { path: 'fines', element: s(<FinesPage />) },
  { path: 'archive', element: s(<StationArchivePage />) },
]
